export type Line = {item: string; quantity: bigint; unitPriceYen: bigint};
export type Invoice = {id: string; customer: string; lines: Line[]};

export function lineAmount(line: Line): bigint {
  return line.quantity * line.unitPriceYen;
}

export function subtotal(invoice: Invoice): bigint {
  return invoice.lines.reduce((sum, line) => sum + lineAmount(line), 0n);
}

