import {Router} from 'express';
import {subtotal, type Invoice} from './invoice.js';

const rows = new Map<string, Invoice>();
export const invoices = Router();

invoices.get('/:id', (req, res) => {
  const inv = rows.get(req.params.id);
  if (!inv) return res.status(404).end();
  res.json({...inv, lines: inv.lines.map((l) => ({...l, quantity: String(l.quantity), unitPriceYen: String(l.unitPriceYen)})), subtotalYen: String(subtotal(inv))});
});

